mapper.select:

SELECT * FROM (
  SELECT owner_id,observation_id AS id,revision,created_at AS occurred_at,
    CONCAT('REVIEWED_OBSERVATION:',observation_id,':-:',revision,':-') AS evidence_key
  FROM reviewed_observation_revision WHERE owner_id=#{owner}
    AND created_at >= #{start} AND created_at < #{end}
) candidate

  WHERE occurred_at < #{afterAt}
    OR (occurred_at=#{afterAt} AND CAST(evidence_key AS BINARY) > CAST(#{afterKey} AS BINARY))

ORDER BY occurred_at DESC,CAST(evidence_key AS BINARY) ASC LIMIT #{pageSize}
